  @Override
  public AssetMetaContext topPriorityForMintChecked(final PublicKey mint) {
    final var mintContext = mintCache.get(mint);
    if (mintContext == null) {
      return null;
    } else {
      return topPriorityForMintChecked(mint, mintContext.decimals());
    }
  }
